import hashlib
import json


def cache_key(tenant, task_digest, policy_version, deployment_revision):
    fields = (tenant, task_digest, policy_version, deployment_revision)
    if any(not isinstance(value, str) or not value.strip() for value in fields):
        raise ValueError("All fields must be nonblank strings")
    payload = json.dumps(fields, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()
